<template>
  <div class="order-issue-badges"><template v-if="active.length"><el-tooltip v-for="issue in displayed" :key="issue.id" :content="(issueScopes[issue.scope] || issue.scope) + ' · ' + (issueStages[issue.stage] || issue.stage) + ' · ' + issue.message" placement="top"><el-tag :type="tone(issue)" size="small" class="issue-tag" tabindex="0" @click="$emit('open')" @keydown.enter.native="$emit('open')">{{ issueCategories[issue.category] || issue.category }}{{ issue.state === 'ACKNOWLEDGED' ? ' · 已确认' : '' }}</el-tag></el-tooltip><el-button v-if="active.length > displayed.length" type="text" size="mini" @click="$emit('open')">更多 {{ active.length - displayed.length }} 项</el-button><span v-if="skuCount" class="issue-caption">影响 {{ skuCount }} 个 SKU</span></template><span v-else class="issue-caption">{{ pending ? '问题待核对' : '无当前问题' }}</span></div>
</template>
<script>
import { issueCategories, issueScopes, issueStages, issueTone } from './issueLabels'
export default { props: { issues: { type: Array, default: () => [] }, pending: Boolean }, data() { return { issueCategories, issueScopes, issueStages } }, computed: { active() { return this.issues.filter(issue => issue.state !== 'RESOLVED') }, displayed() { const categories = new Set(); return this.active.filter(issue => { if (categories.has(issue.category)) return false; categories.add(issue.category); return true }).slice(0, 2) }, skuCount() { return new Set(this.active.map(issue => issue.sku_sn).filter(Boolean)).size } }, methods: { tone: issueTone } }
</script>
<style scoped>.order-issue-badges{display:flex;flex-wrap:wrap;align-items:center;gap:6px}.issue-tag{cursor:pointer}.issue-caption{font-size:12px;color:#8490a2;line-height:1.7}.issue-caption:last-child{flex-basis:100%}.order-issue-badges .el-button{padding:0}</style>
